SELECT , COALESCE(st.store_name, a.activity_name) AS targetName, (SELECT COUNT(*) FROM shop_activity_badge_user bu WHERE bu.badge_id = t.id AND bu.is_deleted = 0) AS issuedUserCount
t.is_deleted = 0
AND (t.badge_name LIKE CONCAT('%', #{q.keyword}, '%') OR t.badge_text LIKE CONCAT('%', #{q.keyword}, '%'))
AND t.badge_type = #{q.badgeType}
AND t.status = #{q.status}
ORDER BY t.status DESC, t.priority DESC, t.id DESC
